17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.HouseholdResolver;
31	import org.springframework.samples.petclinic.mapper.IdentityKeyResolver;
32	import org.springframework.samples.petclinic.mapper.MembershipLevelResolver;
33	import org.springframework.samples.petclinic.mapper.OwnerMapper;
34	import org.springframework.samples.petclinic.mapper.PetMapper;
35	import org.springframework.samples.petclinic.mapper.Region;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
41	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
42	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
43	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
44	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
45	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
46	import org.springframework.samples.petclinic.rest.api.OwnersApi;
47	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
48	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.PetDto;
50	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
51	import org.springframework.samples.petclinic.rest.dto.VisitDto;
52	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
53	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
54	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
55	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
56	import org.springframework.samples.petclinic.service.ClinicService;
57	import org.springframework.security.access.prepost.PreAuthorize;
58	import org.springframework.web.bind.annotation.CrossOrigin;
59	import org.springframework.web.bind.annotation.RequestMapping;
60	import org.springframework.web.bind.annotation.RestController;
61	import org.springframework.web.util.UriComponentsBuilder;
62	
63	import jakarta.transaction.Transactional;
64	
65	/**
66	 * @author Vitaliy Fedoriv
67	 */
68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
75	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
76	
77	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
78	    private static final int MAX_OWNERS_PER_CITY = 50;
79	
80	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
81	    private static final int MAX_OWNERS_PER_DAY = 100;
82	
83	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
84	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    private final TelephoneNormalizer telephoneNormalizer;
95	
96	    private final AddressNormalizer addressNormalizer;
97	
98	    private final EmailNormalizer emailNormalizer;
99	
100	    private final IdentityKeyResolver identityKeyResolver;
101	
102	    private final HouseholdResolver householdResolver;
103	
104	    public OwnerRestControllerV1(ClinicService clinicService,
105	                                 OwnerMapper ownerMapper,
106	                                 PetMapper petMapper,
107	                                 VisitMapper visitMapper,
108	                                 TelephoneNormalizer telephoneNormalizer,
109	                                 AddressNormalizer addressNormalizer,
110	                                 EmailNormalizer emailNormalizer,
111	                                 IdentityKeyResolver identityKeyResolver,
112	                                 HouseholdResolver householdResolver) {
113	        this.clinicService = clinicService;
114	        this.ownerMapper = ownerMapper;
115	        this.petMapper = petMapper;
116	        this.visitMapper = visitMapper;
117	        this.telephoneNormalizer = telephoneNormalizer;
118	        this.addressNormalizer = addressNormalizer;
119	        this.emailNormalizer = emailNormalizer;
120	        this.identityKeyResolver = identityKeyResolver;
121	        this.householdResolver = householdResolver;
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
127	        Collection<Owner> owners;
128	        if (lastName != null) {
129	            owners = this.clinicService.findOwnerByLastName(lastName);
130	        } else {
131	            owners = this.clinicService.findAllOwners();
132	        }
133	        if (owners.isEmpty()) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        owners.forEach(this::populateHouseholdMemberCount);
137	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
138	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
144	        Owner owner = this.clinicService.findOwnerById(ownerId);
145	        if (owner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        populateHouseholdMemberCount(owner);
149	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
150	    }
151	
152	    /**
153	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
154	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
155	     * by the mapper alone.
156	     *
157	     * @param owner the owner to map
158	     * @return the owner DTO carrying its identity key
159	     */
160	    private OwnerDto toOwnerDto(Owner owner) {
161	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
162	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
163	        return ownerDto;
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Transactional
168	    @Override
169	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
170	        normalizeAndValidate(ownerFieldsDto);
171	        HttpHeaders headers = new HttpHeaders();
172	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
173	        populateDerivedFields(owner, ownerFieldsDto);
174	        requireUniqueIdentity(owner);
175	        requireHouseholdNotDuplicate(owner, ownerFieldsDto);
176	        flagPossibleDuplicate(owner, ownerFieldsDto);
177	        this.clinicService.saveOwner(owner);
178	        populateHouseholdMemberCount(owner);
179	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
180	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
181	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount(),
182	                owner.getHouseholdMemberCount(), owner.getRegistrationDate()),
183	            owner.getCustomerCode() + "-M" + String.format("%02d", owner.getRegistrationDate().getYear() % 100));
184	        OwnerDto ownerDto = toOwnerDto(owner);
185	        headers.setLocation(UriComponentsBuilder.newInstance()
186	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
187	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
188	    }
189	
190	    /**
191	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
192	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
193	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
194	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
195	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
196	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
197	     * last name and postcode, so it is in place before {@link #requireUniqueIdentity} derives the identity key. The
198	     * owner is mutated in place; the caller applies the duplicate guards and saves it.
199	     *
200	     * @param owner          the newly mapped owner about to be saved
201	     * @param ownerFieldsDto the incoming owner payload
202	     */
203	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
204	        owner.setCustomerCode(deriveUniqueCustomerCode(owner));
205	        owner.setNamesakeCount(countNamesakes(owner));
206	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
207	        assignHouseholdId(owner);
208	    }
209	
210	    /**
211	     * Derives an owner's {@code customerCode} and de-duplicates it against the owners that already exist. The base code
212	     * is the pure derivation (see {@link IdentityKeyResolver#deriveCustomerCode}); when it collides with an existing
213	     * owner's {@code customerCode} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
214	     * makes the whole code unique. Evaluated before the new owner is saved, so the collision check reflects only owners
215	     * that predate this create; distinct owners therefore always receive distinct customer codes.
216	     *
217	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
218	     * @return the de-duplicated customer code, unique across all existing owners
219	     */
220	    private String deriveUniqueCustomerCode(Owner owner) {
221	        String base = identityKeyResolver.deriveCustomerCode(owner);
222	        Collection<Owner> existing = this.clinicService.findAllOwners();
223	        String candidate = base;
224	        int n = 2;
225	        while (isCustomerCodeInUse(candidate, existing)) {
226	            candidate = base + "-" + n;
227	            n++;
228	        }
229	        return candidate;
230	    }
231	
232	    private boolean isCustomerCodeInUse(String customerCode, Collection<Owner> existing) {
233	        return existing.stream().anyMatch(other -> customerCode.equals(other.getCustomerCode()));
234	    }
235	
236	    /**
237	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
238	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
239	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
240	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
241	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
242	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
243	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
244	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
245	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
246	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
247	     * assigned (see {@link #requireUniqueIdentity}).
248	     *
249	     * @param ownerFieldsDto the incoming owner payload, mutated in place
250	     * @throws MissingOwnerFieldsException if any required field is missing or blank
251	     */
252	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
253	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
254	        validateRequiredFields(ownerFieldsDto);
255	        validatePostcode(ownerFieldsDto);
256	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
257	        ownerFieldsDto.setTelephone(telephone);
258	        requireCityHasCapacity(ownerFieldsDto.getCity());
259	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
260	        ownerFieldsDto.setRegistrationDate(registrationDate);
261	        requireDailyLimitNotReached(registrationDate);
262	        normalizeEmail(ownerFieldsDto);
263	    }
264	
265	    /**
266	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
267	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
268	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
269	     * place so the caller can map and save it directly.
270	     *
271	     * @param ownerFieldsDto the incoming owner payload, mutated in place
272	     */
273	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
274	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
275	    }
276	
277	    /**
278	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
279	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
280	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day. A supplied date
281	     * later than the current server date is rejected.
282	     *
283	     * @param ownerFieldsDto the incoming owner payload
284	     * @return the effective registration date rolled forward onto a business day
285	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
286	     */
287	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
288	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
289	        if (effective == null) {
290	            effective = LocalDate.now();
291	        }
292	        else if (effective.isAfter(LocalDate.now())) {
293	            throw new FutureRegistrationDateException(
294	                "the registration date must not be later than the current server date");
295	        }
296	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
297	            effective = effective.plusDays(1);
298	        }
299	        return effective;
300	    }
301	
302	    /**
303	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
304	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
305	     * further owner may be created for that day.
306	     *
307	     * @param registrationDate the adjusted business-day registration date of the owner being created
308	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
309	     */
310	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
311	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
312	            throw new DailyOwnerLimitExceededException(
313	                "the maximum number of owners for today has already been reached");
314	        }
315	    }
316	
317	    /**
318	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
319	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
320	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
321	     * warning threshold) so both express the same per-day count in one place.
322	     *
323	     * @param registrationDate the adjusted business-day registration date to count owners for
324	     * @return the number of existing owners registered on that day
325	     */
326	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
327	        return this.clinicService.findAllOwners().stream()
328	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
329	            .count();
330	    }
331	
332	    /**
333	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
334	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
335	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
336	     * reflects only owners that predate it.
337	     *
338	     * @param registrationDate the adjusted business-day registration date of the owner being created
339	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
340	     */
341	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
342	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
343	    }
344	
345	    /**
346	     * Counts how many existing owners already share the given owner's first and last name, compared
347	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
348	     * create; it is zero when the owner's name is unique.
349	     *
350	     * @param owner the newly mapped owner about to be saved
351	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
352	     */
353	    private int countNamesakes(Owner owner) {
354	        String firstName = owner.getFirstName();
355	        String lastName = owner.getLastName();
356	        return (int) this.clinicService.findAllOwners().stream()
357	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
358	                && lastName.equalsIgnoreCase(existing.getLastName()))
359	            .count();
360	    }
361	
362	    /**
363	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
364	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
365	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
366	     *
367	     * @param ownerFieldsDto the owner payload to validate
368	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
369	     */
370	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
371	        List<String> missingFields = new ArrayList<>();
372	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
373	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
374	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
375	        requireText(missingFields, "city", ownerFieldsDto.getCity());
376	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
377	        if (!missingFields.isEmpty()) {
378	            throw new MissingOwnerFieldsException(missingFields);
379	        }
380	    }
381	
382	    private void requireText(List<String> missingFields, String fieldName, String value) {
383	        if (value == null || value.isBlank()) {
384	            missingFields.add(fieldName);
385	        }
386	    }
387	
388	    /**
389	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
390	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
391	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
392	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
393	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
394	     *
395	     * @param ownerFieldsDto the incoming owner payload
396	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
397	     */
398	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
399	        String postcode = ownerFieldsDto.getPostcode();
400	        if (postcode == null) {
401	            return;
402	        }
403	        Region region = Region.forCity(ownerFieldsDto.getCity());
404	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
405	            throw new InvalidPostcodeException(
406	                "postcode " + postcode + " is not valid for the city's region " + region.name());
407	        }
408	    }
409	
410	    /**
411	     * Rejects creating an owner whose whole derived {@code identityKey} (see
412	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
413	     * duplicate only when its normalized telephone, email and {@code householdId} all match another owner's. It runs
414	     * after the household id has been assigned, so the key reflects the household the owner belongs to. Owners that
415	     * share only their household (same last name and postcode, different telephone) are not caught here but by the
416	     * separate household-duplicate guard (see {@link #requireHouseholdNotDuplicate}).
417	     *
418	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
419	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
420	     */
421	    private void requireUniqueIdentity(Owner owner) {
422	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
423	        boolean inUse = this.clinicService.findAllOwners().stream()
424	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
425	        if (inUse) {
426	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
427	        }
428	    }
429	
430	    /**
431	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared both the hard-duplicate
432	     * guard (see {@link #requireUniqueIdentity}) and the household-duplicate guard (see
433	     * {@link #requireHouseholdNotDuplicate}), so it is still being created; this only records a warning. A declared
434	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
435	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
436	     * duplicate when some existing owner shares its last name (compared case-insensitively) and its postcode but
437	     * carries a different telephone. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
438	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
439	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
440	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
441	     *
442	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
443	     * @param ownerFieldsDto the incoming owner payload
444	     */
445	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
446	        owner.setPossibleDuplicate(false);
447	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
448	            return;
449	        }
450	        String postcode = owner.getPostcode();
451	        if (postcode == null || postcode.isBlank()) {
452	            return;
453	        }
454	        String lastName = owner.getLastName();
455	        String telephone = owner.getTelephone();
456	        for (Owner existing : this.clinicService.findAllOwners()) {
457	            if (lastName.equalsIgnoreCase(existing.getLastName())
458	                && postcode.equals(existing.getPostcode())
459	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
460	                owner.setPossibleDuplicate(true);
461	                owner.setPossibleDuplicateOf(existing.getId());
462	                return;
463	            }
464	        }
465	    }
466	
467	    /**
468	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
469	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
470	     *
471	     * @param city the city of the owner being created
472	     * @throws OwnerCityFullException if the city already contains 50 or more owners
473	     */
474	    private void requireCityHasCapacity(String city) {
475	        long cityOwners = this.clinicService.findAllOwners().stream()
476	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
477	            .count();
478	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
479	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
480	        }
481	    }
482	
483	    /**
484	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
485	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
486	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
487	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
488	     * such owners never match one another as a household.
489	     *
490	     * @param owner the newly mapped owner about to be saved
491	     */
492	    private void assignHouseholdId(Owner owner) {
493	        String postcode = owner.getPostcode();
494	        if (postcode == null || postcode.isBlank()) {
495	            owner.setHouseholdId(null);
496	            return;
497	        }
498	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
499	    }
500	
501	    /**
502	     * Rejects creating an owner that would join an existing household it has not declared. Because the household is
503	     * keyed on the last name and postcode (see {@link #assignHouseholdId}), any existing owner carrying the same
504	     * derived {@code householdId} is a member of the same household. A second such owner is a household duplicate and is
505	     * rejected, unless the payload sets {@code sharesHousehold} to {@code true}, which declares the owner a genuine
506	     * household member and lets the create proceed. An owner with no household ({@code null} householdId, i.e. created
507	     * without a postcode) can never be a household duplicate.
508	     *
509	     * @param owner          the newly mapped owner about to be saved, with its household id already assigned
510	     * @param ownerFieldsDto the incoming owner payload
511	     * @throws DuplicateOwnerException if an existing owner already belongs to this household and the create did not
512	     *                                 declare {@code sharesHousehold}
513	     */
514	    private void requireHouseholdNotDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
515	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
516	            return;
517	        }
518	        String householdId = owner.getHouseholdId();
519	        if (householdId == null) {
520	            return;
521	        }
522	        boolean sharedByExisting = this.clinicService.findAllOwners().stream()
523	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
524	        if (sharedByExisting) {
525	            throw new DuplicateOwnerException("an owner in the same household already exists");
526	        }
527	    }
528	
529	    /**
530	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
531	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
532	     * household is counted as a household of one.
533	     *
534	     * @param owner the owner whose household size should be resolved
535	     */
536	    private void populateHouseholdMemberCount(Owner owner) {
537	        String householdId = owner.getHouseholdId();
538	        if (householdId == null) {
539	            owner.setHouseholdMemberCount(1);
540	            return;
541	        }
542	        long members = this.clinicService.findAllOwners().stream()
543	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
544	            .count();
545	        owner.setHouseholdMemberCount((int) members);
546	    }
547	
548	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
549	    @Override
550	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
551	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
552	        if (currentOwner == null) {
553	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
554	        }
555	        validatePostcode(ownerFieldsDto);
556	        currentOwner.setAddress(ownerFieldsDto.getAddress());
557	        currentOwner.setCity(ownerFieldsDto.getCity());
558	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
559	        currentOwner.setLastName(ownerFieldsDto.getLastName());
560	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
561	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
562	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
563	        this.clinicService.saveOwner(currentOwner);
564	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
565	    }
566	
567	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
568	    @Transactional
569	    @Override
570	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
571	        Owner owner = this.clinicService.findOwnerById(ownerId);
572	        if (owner == null) {
573	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
574	        }
575	        this.clinicService.deleteOwner(owner);
576	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
577	    }
578	
579	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
580	    @Override
581	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
582	        Owner owner = this.clinicService.findOwnerById(ownerId);
583	        if (owner == null) {
584	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
585	        }
586	        HttpHeaders headers = new HttpHeaders();
587	        Pet pet = petMapper.toPet(petFieldsDto);
588	        owner.setId(ownerId);
589	        pet.setOwner(owner);
590	        pet.getType().setName(null);
591	        this.clinicService.savePet(pet);
592	        PetDto petDto = petMapper.toPetDto(pet);
593	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
594	            .buildAndExpand(pet.getId()).toUri());
595	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
596	    }
597	
598	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
599	    @Override
600	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
601	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
602	        if (currentOwner != null) {
603	            Pet currentPet = this.clinicService.findPetById(petId);
604	            if (currentPet != null) {
605	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
606	                currentPet.setName(petFieldsDto.getName());
607	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
608	                this.clinicService.savePet(currentPet);
609	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
610	            }
611	        }
612	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
613	    }
614	
615	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
616	    @Override
617	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
618	        HttpHeaders headers = new HttpHeaders();
619	        Visit visit = visitMapper.toVisit(visitFieldsDto);
620	        Pet pet = new Pet();
621	        pet.setId(petId);
622	        visit.setPet(pet);
623	        this.clinicService.saveVisit(visit);
624	        VisitDto visitDto = visitMapper.toVisitDto(visit);
625	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
626	            .buildAndExpand(visit.getId()).toUri());
627	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
628	    }
629	
630	
631	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
632	    @Override
633	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
634	        Owner owner = this.clinicService.findOwnerById(ownerId);
635	        if (owner != null) {
636	            Pet pet = owner.getPet(petId);
637	            if (pet != null) {
638	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
639	            }
640	        }
641	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
642	    }
643	}
